from lessonlib import *
RFC = lambda n, t: REF('RFC %s: %s' % (n, t), 'https://www.rfc-editor.org/rfc/rfc%s' % n)
IEEE8021 = REF('IEEE 802.1 working group (bridging, VLANs, STP, LACP)', 'https://1.ieee802.org/')

write('ospf',
 "OSPF is a link-state interior gateway protocol. Every router learns the full topology of its area, then independently runs Dijkstra's shortest-path-first algorithm to build its routing table, so all routers converge on consistent loop-free routes.",
 [S('Link-state idea', "Each router describes its own links and neighbours in Link State Advertisements (LSAs) and floods them. All routers in an area end up with an identical link-state database (LSDB), then each computes a shortest-path tree rooted at itself (RFC 2328). OSPF uses a single dimensionless cost metric summed along the path; a common convention is cost = reference bandwidth / interface bandwidth."),
  S('Neighbour discovery: Hello protocol', "Routers send Hello packets (to multicast 224.0.0.5, IP protocol 89) at the hello interval (10 s on broadcast links by default). Neighbours must agree on area, hello and dead intervals, and authentication. The dead interval (default 40 s) declares a silent neighbour down.", bullets=["Down: no Hello received.", "Init: Hello received but our router ID not yet seen in it.", "2-Way: bidirectional communication confirmed; DR/BDR election happens here.", "ExStart / Exchange: master/slave negotiation, then database descriptions are swapped.", "Loading: missing LSAs are requested.", "Full: databases are synchronized; the routers are adjacent."]),
  S('Designated Router', "On a broadcast segment every router forming a full mesh of adjacencies would flood needlessly. Instead, a Designated Router (DR) and Backup (BDR) are elected by highest priority, then highest router ID; other routers form adjacencies only with the DR and BDR. DR/BDR listen on 224.0.0.6."),
  S('Areas', "A large network is split into areas to limit flooding and SPF scope. Area 0, the backbone, must be contiguous and connect all other areas (virtual links can patch gaps). Area Border Routers (ABRs) summarize routes between areas; ASBRs inject external routes.", bullets=["Internal router: all interfaces in one area.", "ABR: interfaces in multiple areas.", "Backbone router: at least one interface in area 0.", "ASBR: redistributes routes from outside the OSPF domain."]),
  S('LSA types and flooding', None, bullets=["Type 1 Router LSA: a router's links within an area.", "Type 2 Network LSA: generated by the DR for a multi-access segment.", "Type 3 Summary LSA: inter-area routes from an ABR.", "Type 5 AS-external LSA: routes from an ASBR.", "LSAs carry sequence numbers and an age; they are refreshed every 30 minutes and expire at 60 minutes.", "Flooding is reliable: each LSA is acknowledged."])],
 [SUB('SPF calculation', 'Dijkstra on the LSDB.', S(None, "Start with the router itself at cost 0; repeatedly add the unvisited vertex with the lowest cumulative cost and relax its neighbours. The result is a shortest-path tree from which next hops are derived. A topology change triggers a rerun, often throttled to avoid churn.")),
  SUB('Why OSPF converges quickly', 'Compared with distance-vector.', S(None, "Changes are flooded immediately and each router recomputes locally, rather than routes propagating hop by hop with counting-to-infinity risks. Features like fast hello and BFD shorten failure detection to sub-second.")),
  SUB('Network types', 'Broadcast, point-to-point, NBMA.', S(None, "Broadcast and NBMA networks elect a DR; point-to-point links do not. Mismatched network types are a common cause of neighbours stuck in a state.")),
  SUB('Troubleshooting stuck neighbours', 'Checklist.', S(None, bullets=["Stuck in Init: one-way communication; check ACLs and multicast.", "Stuck in ExStart/Exchange: usually an MTU mismatch.", "No neighbour: mismatched area ID, hello/dead timers, subnet mask, or authentication.", "Useful commands: show ip ospf neighbor, show ip ospf database, show ip route ospf."])),
  SUB('OSPFv3 and IS-IS', 'Alternatives.', S(None, "OSPFv3 (RFC 5340) carries IPv6 and runs per link. IS-IS is a similar link-state protocol popular in service-provider backbones."))],
 ["Link-state: flood LSAs, build the same LSDB everywhere, run SPF locally.", "Neighbour states: Down, Init, 2-Way, ExStart, Exchange, Loading, Full.", "Area 0 is the backbone; ABRs connect areas; a DR/BDR reduces adjacencies on LANs.", "Cost is the metric; MTU, timers, and area mismatches break adjacency."],
 [RFC('2328', 'OSPF Version 2'), RFC('5340', 'OSPF for IPv6'), REF('Reference: Dijkstra routing animation background', 'https://en.wikipedia.org/wiki/Open_Shortest_Path_First')])

write('bgp',
 "BGP-4 is the path-vector protocol that connects autonomous systems and glues the Internet together. Instead of shortest paths it applies policy: each AS decides which routes to accept, prefer, and advertise.",
 [S('Autonomous systems and peering', "An autonomous system (AS) is a set of routers under one administration with a number (ASN). Routers in different ASes peer via eBGP; routers in the same AS exchange routes via iBGP. BGP runs over TCP port 179 (RFC 4271), so it relies on TCP for reliability and has no routing-update retransmission of its own."),
  S('Message types', None, bullets=["OPEN: starts a session; carries ASN, hold time, BGP identifier, capabilities.", "KEEPALIVE: proves the peer is alive (typically sent at one third of the hold time).", "UPDATE: advertises new routes (NLRI + path attributes) or withdraws old ones.", "NOTIFICATION: reports an error and closes the session."]),
  S('Session state machine', "Idle, Connect, Active, OpenSent, OpenConfirm, Established. Routes are exchanged only in Established. A session stuck in Active usually means the TCP connection cannot be made (wrong neighbour address, firewall, or missing route)."),
  S('Path attributes', None, bullets=["AS_PATH: the list of ASes the route traversed; each AS prepends its own number when advertising to an eBGP peer. Also used for loop prevention: a router rejects a route containing its own ASN.", "NEXT_HOP: the address to forward to.", "ORIGIN: how the route entered BGP (IGP, EGP, incomplete).", "LOCAL_PREF: preference inside an AS; higher is better; not sent to other ASes.", "MED: hint to a neighbour AS about the preferred entry point; lower is better."]),
  S('Best-path selection', "When several routes to the same prefix exist, BGP picks one in a fixed order (RFC 4271 section 9.1):", bullets=["Highest LOCAL_PREF.", "Shortest AS_PATH.", "Lowest ORIGIN (IGP < EGP < incomplete).", "Lowest MED (among routes from the same neighbouring AS).", "Prefer eBGP over iBGP.", "Lowest IGP cost to the NEXT_HOP.", "Lowest BGP identifier (final tie-breaker)."])],
 [SUB('Policy and business relationships', 'Customer, peer, provider.', S(None, "ASes prefer routes from customers (they pay) over peers (settlement-free) over providers (cost money), by setting LOCAL_PREF. They filter exports so they do not give free transit: customer routes go to everyone, peer and provider routes go only to customers.")),
  SUB('iBGP rules', 'Full mesh, route reflectors, confederations.', S(None, "A router does not re-advertise a route learned from one iBGP peer to another iBGP peer, to avoid loops. So iBGP needs a full mesh, or route reflectors (RFC 4456) or confederations to scale.")),
  SUB('Why BGP converges slowly', 'Path exploration.', S(None, "A withdrawn route may trigger a sequence of progressively longer alternative paths before settling. Timers such as MRAI (minimum route advertisement interval) and route-flap damping add delay, so global convergence can take minutes.")),
  SUB('Prefix hijacks and RPKI', 'Security gaps.', S(None, "BGP trusts what neighbours announce. A mistaken or malicious announcement of someone else's prefix can attract traffic. RPKI route-origin validation (ROV) and prefix filtering reduce this; BGPsec adds path validation but is rarely deployed.")),
  SUB('Communities', 'Tagging routes.', S(None, "Communities (RFC 1997) are 32-bit tags attached to routes, such as 'do not export' or 'set local preference 80', letting neighbours signal policy without per-route configuration."))],
 ["BGP is a path-vector protocol between ASes over TCP port 179.", "AS_PATH carries the route history and prevents loops.", "Best path: LOCAL_PREF, then shortest AS_PATH, then origin, MED, eBGP over iBGP, IGP cost, router ID.", "Policy, not speed, drives BGP; security relies on filtering and RPKI."],
 [RFC('4271', 'A Border Gateway Protocol 4 (BGP-4)'), RFC('1997', 'BGP Communities Attribute'), RFC('6811', 'BGP Prefix Origin Validation')])

write('tcp-handshake',
 "TCP opens a connection with a three-way handshake: SYN, SYN-ACK, ACK. It agrees initial sequence numbers and confirms that both sides can send and receive before any data flows.",
 [S('The exchange (RFC 9293, section 3.5)', "Client calls connect(); server is in LISTEN. Example initial sequence numbers 100 (client) and 300 (server):", code="Client                          Server\nCLOSED                          LISTEN\n  --- SYN seq=100 ----------->  \nSYN-SENT                        SYN-RECEIVED\n  <-- SYN+ACK seq=300 ack=101 -- \nESTABLISHED                     \n  --- ACK seq=101 ack=301 ----->  \n                                ESTABLISHED"),
  S('Why three steps', "Each side must send a SYN and have it acknowledged. The server's SYN and its ACK of the client's SYN are combined into one packet (SYN+ACK), so four messages become three. Both directions are thereby synchronized."),
  S('What is negotiated', None, bullets=["Initial sequence numbers (ISNs), one per direction.", "Maximum Segment Size (MSS) option.", "Window scale factor, SACK-permitted, and timestamps options.", "Receive windows."]),
  S('Initial sequence numbers', "ISNs must be unpredictable, otherwise an attacker can forge segments. RFC 9293 describes ISN = a 4-microsecond clock + a keyed hash of the connection 4-tuple and a secret that outsiders cannot compute."),
  S('SYN consumes a sequence number', "A SYN counts as one byte of sequence space, which is why the acknowledgment is ISN+1 (101 and 301 above).")],
 [SUB('TCP states during setup', 'Client and server views.', S(None, bullets=["Client: CLOSED -> SYN-SENT -> ESTABLISHED.", "Server: CLOSED -> LISTEN -> SYN-RECEIVED -> ESTABLISHED."])),
  SUB('SYN flood and SYN cookies', 'Attack on the half-open state.', S(None, "A flood of SYNs fills the server's half-open queue. SYN cookies encode state in the server's ISN so no memory is held until the final ACK returns with a valid cookie, letting the connection be rebuilt.")),
  SUB('Simultaneous open', 'Both sides send SYN at once.', S(None, "Rare but required: each moves SYN-SENT -> SYN-RECEIVED on seeing the other's SYN and then to ESTABLISHED after the SYN+ACKs, using four segments.")),
  SUB('Connection refused and RST', 'When there is no listener.', S(None, "A SYN to a closed port draws a RST, and the client sees 'connection refused'. A silent timeout instead means a firewall dropped the SYN.")),
  SUB('TCP Fast Open and QUIC', 'Cutting round trips.', S(None, "TCP Fast Open lets data ride in the SYN on repeat connections. QUIC merges transport and TLS setup, needing one round trip (or zero on resumption)."))],
 ["SYN, SYN+ACK, ACK synchronizes sequence numbers in both directions.", "SYN consumes one sequence number; ACK = ISN + 1.", "Options like MSS, window scale, and SACK are negotiated in the SYNs.", "Randomized ISNs and SYN cookies defend against spoofing and floods."],
 [RFC('9293', 'Transmission Control Protocol (TCP)'), RFC('4987', 'TCP SYN Flooding Attacks and Common Mitigations'), RFC('7323', 'TCP Extensions for High Performance')])

write('tcp-teardown',
 "A TCP connection is closed independently in each direction using FIN segments, so a full close normally takes four segments. The side that closes first lingers in TIME-WAIT to make sure the final ACK arrives and old segments die out.",
 [S('Normal close (RFC 9293, section 3.6)', None, code="Active closer                    Passive closer\nESTABLISHED                      ESTABLISHED\n  --- FIN seq=x ------------->\nFIN-WAIT-1                       CLOSE-WAIT\n  <-- ACK ack=x+1 -----------\nFIN-WAIT-2\n                                 (app calls close)\n  <-- FIN seq=y ------------\n                                 LAST-ACK\n  --- ACK ack=y+1 ---------->\nTIME-WAIT (2 x MSL)              CLOSED\nCLOSED"),
  S('State meanings', None, bullets=["FIN-WAIT-1: our FIN sent, waiting for its ACK.", "FIN-WAIT-2: our FIN acknowledged, waiting for the peer's FIN.", "CLOSE-WAIT: peer's FIN received; waiting for our application to close.", "LAST-ACK: our FIN sent after CLOSE-WAIT; waiting for the final ACK.", "TIME-WAIT: waiting before deleting the connection record.", "CLOSING: both sides sent FIN simultaneously."]),
  S('Why four segments', "Each direction is closed separately. The peer may still have data to send after receiving our FIN (a half-close), so its ACK and its own FIN can be separated in time. If it has nothing more to send they can be combined, giving three segments."),
  S('TIME-WAIT', "The active closer must remain in TIME-WAIT for 2 x MSL (RFC 9293 requires 2 x the maximum segment lifetime; MSL is commonly assumed 60 s on Linux, giving a 60 s wait in practice). It guarantees the last ACK can be retransmitted if lost and prevents delayed segments from a previous connection being mistaken for a new one using the same 4-tuple."),
  S('Abortive close', "A RST ends a connection immediately with no handshake. It is sent for segments to a non-existent connection and when SO_LINGER with zero timeout is used. Pending data is discarded.")],
 [SUB('Half-close', 'shutdown(SHUT_WR).', S(None, "An application can send a FIN yet keep reading, as in HTTP clients that signal 'request done' while waiting for the response. shutdown(fd, SHUT_WR) does this; close() ends both directions.")),
  SUB('Too many TIME-WAIT sockets', 'High-rate clients.', S(None, "Servers that actively close thousands of connections per second accumulate TIME-WAIT entries and may exhaust ephemeral ports. Remedies: let the client close first, reuse connections (keep-alive), and use SO_REUSEADDR or tcp_tw_reuse for outgoing connections.")),
  SUB('Too many CLOSE-WAIT sockets', 'A program bug.', S(None, "CLOSE-WAIT piling up means the peer closed but the local application never called close(), a classic file-descriptor leak. TIME-WAIT is normal; CLOSE-WAIT growth is not.")),
  SUB('Simultaneous close', 'Both ends send FIN together.', S(None, "Both go FIN-WAIT-1 -> CLOSING -> TIME-WAIT after exchanging FINs and ACKs; each side waits 2 x MSL.")),
  SUB('Inspecting states', 'Tools.', S(None, "`ss -tan state time-wait | wc -l` counts TIME-WAIT sockets; `ss -tan` lists all TCP states.", code="$ ss -tan | awk '{print $1}' | sort | uniq -c"))],
 ["Each direction closes with its own FIN and ACK, usually four segments.", "The active closer ends in TIME-WAIT for 2 x MSL.", "CLOSE-WAIT buildup indicates an application not closing sockets.", "RST aborts a connection immediately."],
 [RFC('9293', 'Transmission Control Protocol (TCP)'), RFC('1337', 'TIME-WAIT Assassination Hazards in TCP')])

write('dns-resolution',
 "DNS translates names such as www.example.com into IP addresses through a hierarchy of servers. A stub resolver asks a recursive resolver, which walks the hierarchy from the root down and caches the answers.",
 [S('The hierarchy', "Names are read right to left: root (.), top-level domain (com), second-level (example), host (www). Each level is a zone served by authoritative name servers that delegate to the next level with NS records (RFC 1035)."),
  S('Resolution walk', "For a cold cache the recursive resolver performs iterative queries:", code="1. Client -> recursive resolver: www.example.com A?\n2. Resolver -> root server: referral to .com TLD servers\n3. Resolver -> .com TLD server: referral to example.com name servers\n4. Resolver -> example.com authoritative: A 93.184.216.34, TTL 3600\n5. Resolver caches it and answers the client"),
  S('Message format', "A DNS message has a 12-byte header (ID, flags, and four counts) followed by Question, Answer, Authority, and Additional sections. Flags include QR (query/response), AA (authoritative), TC (truncated), RD (recursion desired), RA (recursion available), and RCODE.", bullets=["The ID matches responses to queries.", "Names are sequences of length-prefixed labels, and may be compressed with 2-byte pointers to earlier occurrences.", "Resource records have NAME, TYPE, CLASS, TTL, RDLENGTH, RDATA."]),
  S('Record types', None, bullets=["A / AAAA: IPv4 / IPv6 address.", "NS: authoritative name server for a zone.", "CNAME: alias to a canonical name.", "MX: mail exchanger with a preference.", "PTR: reverse lookup from address to name.", "TXT: free text (SPF, DKIM, verification).", "SOA: zone authority and timers."]),
  S('Transport', "DNS uses UDP port 53 for normal queries and TCP port 53 for zone transfers and when responses are truncated (TC bit). The original UDP limit was 512 bytes; EDNS0 (RFC 6891) lets clients advertise larger buffers.")],
 [SUB('Caching and TTL', 'Why DNS scales.', S(None, "Every record carries a TTL telling resolvers how long to cache it. Caching, including negative caching of NXDOMAIN (RFC 2308), absorbs most queries; lowering a TTL before a migration speeds failover.")),
  SUB('Recursive versus iterative', 'Who does the work.', S(None, "A stub resolver asks for a complete answer (recursive query). The resolver then queries servers iteratively, following referrals. Authoritative servers normally do not recurse for outsiders.")),
  SUB('DNSSEC', 'Authenticating answers.', S(None, "DNSSEC signs records (RRSIG), publishes keys (DNSKEY), and chains trust from the root through DS records, letting validators detect forged answers. It authenticates data but does not encrypt queries.")),
  SUB('Encrypted DNS', 'DoT and DoH.', S(None, "DNS over TLS (RFC 7858, port 853) and DNS over HTTPS (RFC 8484) hide queries from on-path observers.")),
  SUB('Debugging with dig', 'Common commands.', S(None, "`dig +trace example.com` shows the delegation walk; `dig @8.8.8.8 example.com MX` queries a specific server; `dig -x 8.8.8.8` does a reverse lookup.", code="$ dig +short example.com A\n93.184.216.34"))],
 ["DNS is a hierarchy: root, TLD, domain, host; NS records delegate.", "Resolvers cache by TTL; a cold lookup walks root -> TLD -> authoritative.", "UDP/53 normally, TCP/53 for large responses and zone transfers.", "DNSSEC authenticates; DoT/DoH encrypt."],
 [RFC('1035', 'Domain Names - Implementation and Specification'), RFC('1034', 'Domain Names - Concepts and Facilities'), RFC('4033', 'DNS Security Introduction and Requirements')])

write('dhcp-lease',
 "DHCP automatically gives a host an IP address, mask, gateway, and DNS servers for a limited lease. A client finds a server with a broadcast, accepts an offer, and renews before the lease expires.",
 [S('The four-message exchange (DORA)', "RFC 2131 defines the sequence. Clients use UDP port 68 and servers port 67. The client has no address yet, so it sends from 0.0.0.0 to 255.255.255.255.", code="Client                               Server\n  --- DHCPDISCOVER (broadcast) --->   find servers\n  <-- DHCPOFFER  (offers address)\n  --- DHCPREQUEST (broadcast) ---->   accept one offer\n  <-- DHCPACK    (lease details)       committed"),
  S('Why REQUEST is broadcast', "If several servers offered, the client's broadcast REQUEST names the chosen server so the others can withdraw their offers and free the address."),
  S('What the ACK carries', None, bullets=["yiaddr: the assigned address.", "Options: subnet mask (1), router (3), DNS servers (6), lease time (51), domain name (15), and more.", "The transaction ID (xid) and client hardware address (chaddr) identify the client."]),
  S('Lease lifecycle and timers', None, bullets=["BOUND: the client uses the address and sets timers.", "T1 = 50% of the lease: enter RENEWING and unicast a REQUEST to the original server.", "T2 = 87.5%: if still unanswered, enter REBINDING and broadcast a REQUEST to any server.", "At 100%: the lease expires, the client must stop using the address and restart in INIT.", "DHCPRELEASE hands the address back early."]),
  S('Other messages', None, bullets=["DHCPNAK: server says the requested address is invalid (client moved networks).", "DHCPDECLINE: client found the offered address already in use (ARP probe) and rejects it.", "DHCPINFORM: client has an address but wants configuration options only."])],
 [SUB('Relay agents', 'Crossing routers.', S(None, "Broadcasts do not cross routers, so a relay agent on the client's subnet forwards requests to the server as unicast and records its own address in giaddr. The server uses giaddr to choose the right scope and replies via the relay.")),
  SUB('Client states', 'INIT to BOUND.', S(None, "INIT -> SELECTING (collect offers) -> REQUESTING -> BOUND -> RENEWING -> REBINDING, with a return to INIT on NAK or expiry.")),
  SUB('Reservations and scopes', 'Server configuration.', S(None, "A scope is the pool and options for a subnet. Reservations bind a MAC address to a fixed IP so a device such as a printer always receives the same address.")),
  SUB('Security: rogue servers and starvation', 'Attacks and defences.', S(None, "A rogue DHCP server can hand out a malicious gateway or DNS. Starvation attacks exhaust the pool with fake MACs. Switch features: DHCP snooping (only trusted ports may send server replies, and it builds a binding table) and port security.")),
  SUB('DHCPv6', 'IPv6 equivalent.', S(None, "DHCPv6 (RFC 8415) uses Solicit, Advertise, Request, and Reply on UDP 546/547. Often combined with SLAAC; prefix delegation hands routers a whole prefix."))],
 ["DORA: Discover, Offer, Request, Ack; UDP 67 (server) and 68 (client).", "Leases renew at T1 = 50% (unicast) and T2 = 87.5% (broadcast).", "Relay agents carry requests across routers using giaddr.", "Protect with DHCP snooping."],
 [RFC('2131', 'Dynamic Host Configuration Protocol'), RFC('2132', 'DHCP Options and BOOTP Vendor Extensions'), RFC('8415', 'DHCP for IPv6')])

write('tls-handshake',
 "The TLS handshake lets a client and server agree on protocol parameters, authenticate the server (and optionally the client), and derive shared secret keys. In TLS 1.3 this takes one round trip, and everything after ServerHello is encrypted.",
 [S('TLS 1.3 full handshake (RFC 8446)', None, code="Client                                   Server\n ClientHello  (+key_share, supported_versions,\n               signature_algorithms) ------->\n                                      ServerHello (+key_share)\n                                     {EncryptedExtensions}\n                                     {Certificate}\n                                     {CertificateVerify}\n                          <-------   {Finished}\n {Finished} ------------------------>\n [Application Data] <--------------> [Application Data]\n  ({ } = encrypted with handshake keys)"),
  S('What each message does', None, bullets=["ClientHello: random nonce, supported versions and cipher suites, and key shares for (EC)DHE.", "ServerHello: chosen cipher suite and the server's key share; both sides can now derive handshake keys.", "EncryptedExtensions: remaining extension responses.", "Certificate: the server's certificate chain.", "CertificateVerify: a signature over the transcript proving possession of the private key.", "Finished: a MAC over the whole handshake confirming nothing was altered."]),
  S('Key exchange and forward secrecy', "Both sides exchange ephemeral Diffie-Hellman shares (X25519 or P-256) and compute the same shared secret. The keys are fed through HKDF in a key schedule to produce handshake and application traffic keys. Because the DH keys are discarded after use, recording traffic and later stealing the server's long-term key does not reveal past sessions: forward secrecy. TLS 1.3 removed static RSA and static DH key exchange."),
  S('Authentication', "The client validates the certificate chain up to a trusted root, checks the hostname against the certificate's subject alternative names, validity dates, and revocation status. CertificateVerify proves the server actually holds the key.")],
 [SUB('What changed from TLS 1.2', 'Fewer round trips, fewer algorithms.', S(None, bullets=["1-RTT instead of 2-RTT for a full handshake.", "Only AEAD ciphers (AES-GCM, ChaCha20-Poly1305).", "Handshake messages after ServerHello are encrypted.", "Static RSA and DH, RC4, CBC, and compression removed.", "Versions negotiated via the supported_versions extension."])),
  SUB('Session resumption and 0-RTT', 'Faster reconnects.', S(None, "A server can issue a ticket derived from a previous session; the client sends a pre-shared key identity and can include early data in its first flight (0-RTT). Early data is not forward secret and can be replayed, so use it only for idempotent requests.")),
  SUB('SNI and ALPN', 'Extensions you meet daily.', S(None, "Server Name Indication tells the server which hostname the client wants so one IP can host many certificates. ALPN negotiates the application protocol such as h2 or http/1.1. Encrypted Client Hello hides SNI.")),
  SUB('Record layer', 'Protecting application data.', S(None, "Data is split into records, encrypted and authenticated with AEAD using per-record nonces, and padded optionally. The TCP segment sizes then reveal little about the content.")),
  SUB('Inspecting a handshake', 'OpenSSL.', S(None, "`openssl s_client -connect example.com:443 -tls1_3` prints the negotiated version, cipher, and certificate chain; Wireshark shows the ClientHello fields until encryption begins.", code="$ openssl s_client -connect example.com:443 -tls1_3 </dev/null"))],
 ["Client and server exchange ephemeral key shares to derive shared secrets.", "TLS 1.3 handshakes in 1 RTT and encrypts everything after ServerHello.", "Certificate + CertificateVerify + Finished authenticate the server and the transcript.", "Forward secrecy is mandatory; 0-RTT trades safety for speed."],
 [RFC('8446', 'The Transport Layer Security (TLS) Protocol Version 1.3'), RFC('5280', 'Internet X.509 PKI Certificate and CRL Profile'), RFC('7301', 'TLS ALPN Extension')])

write('mac-learning',
 "A Layer 2 switch builds its forwarding table automatically by watching source MAC addresses. It then forwards frames only to the port where the destination lives and floods when it does not know.",
 [S('Learning from the source address', "For every frame that arrives, the switch records (source MAC, ingress port, VLAN) in its MAC address table (often kept in CAM hardware). This is how it discovers where each device is, with no configuration."),
  S('Forwarding decision', "The switch then looks up the destination MAC:", bullets=["Known unicast: forward out the single learned port.", "Destination on the same port it arrived: filter (drop), no need to forward.", "Unknown unicast: flood out all ports in the VLAN except the ingress port.", "Broadcast (ff:ff:ff:ff:ff:ff): flood.", "Multicast: flood unless IGMP/MLD snooping limits it."]),
  S('Worked example', None, code="Switch with hosts A (port 1), B (port 2), C (port 3); table empty.\n1. A -> B: learn A=port1. B unknown -> flood to ports 2,3.\n2. B -> A: learn B=port2. A known -> forward only to port 1.\n3. A -> B again: B known -> forward only to port 2. C no longer sees it."),
  S('Aging', "Entries are removed after an idle aging time (commonly 300 seconds) so the table does not fill with stale devices and moved hosts are relearned. If a MAC appears on a different port, the entry is updated; that is how a laptop moving between ports is tracked.")],
 [SUB('Collision and broadcast domains', 'What a switch separates.', S(None, "Each switch port is its own collision domain, but all ports in a VLAN share one broadcast domain. Routers or Layer 3 switches separate broadcast domains.")),
  SUB('Store-and-forward vs cut-through', 'Switching modes.', S(None, "Store-and-forward receives the whole frame and checks the FCS before forwarding, discarding bad frames. Cut-through starts forwarding once the destination MAC is read, lowering latency but passing errors along.")),
  SUB('MAC flooding attack', 'Overflowing the table.', S(None, "An attacker sends frames with thousands of fake source MACs until the table is full; the switch then floods unknown unicast like a hub, letting the attacker sniff. Port security (limit MACs per port) and dynamic ARP inspection mitigate it.")),
  SUB('MAC flapping', 'A symptom of a loop.', S(None, "If the same MAC keeps jumping between ports, there is usually a Layer 2 loop or a duplicate MAC. Logs show 'MAC flapping'; check spanning tree.")),
  SUB('Viewing the table', 'Commands.', S(None, "Cisco: `show mac address-table`. Linux bridge: `bridge fdb show`. Both list MAC, VLAN, port, and whether it is dynamic or static.", code="Switch# show mac address-table\nVlan  Mac Address       Type     Ports\n   1  aaaa.bbbb.0001    DYNAMIC  Gi0/1"))],
 ["Switches learn source MAC to port mappings automatically.", "Known unicast goes out one port; unknown unicast and broadcast are flooded.", "Entries age out (about 300 s) and update when a host moves.", "A full MAC table makes a switch behave like a hub; limit it with port security."],
 [REF('IEEE 802.1D MAC Bridges', 'https://1.ieee802.org/'), REF('Reference: Network switch (Wikipedia)', 'https://en.wikipedia.org/wiki/Network_switch')])

write('vlan',
 "A VLAN divides one physical switch network into separate logical Layer 2 broadcast domains. IEEE 802.1Q tags frames with a VLAN ID so many VLANs can share one trunk link.",
 [S('Why VLANs', None, bullets=["Segment traffic by department, function, or security zone without separate hardware.", "Shrink broadcast domains for performance.", "Move users without recabling.", "Each VLAN is typically one IP subnet."]),
  S('The 802.1Q tag', "A 4-byte tag is inserted after the source MAC address:", code="| Dst MAC | Src MAC | TPID 0x8100 (16) | PCP (3) | DEI (1) | VID (12) | EtherType | Payload | FCS |", bullets=["TPID: 0x8100 identifies a tagged frame.", "PCP: priority (class of service) 0-7.", "DEI: drop eligibility.", "VID: VLAN ID; usable values 1-4094 (0 and 4095 are reserved).", "The tag adds 4 bytes, raising the maximum frame to 1522; the FCS is recalculated."]),
  S('Port types', None, bullets=["Access port: belongs to one VLAN and sends/receives untagged frames; for end hosts.", "Trunk port: carries many VLANs with tags; between switches, or to routers and servers.", "Native VLAN: frames on a trunk without a tag are assigned to it; both ends must agree."]),
  S('Inter-VLAN routing', "Hosts in different VLANs are in different subnets, so traffic must be routed. Options: router-on-a-stick (a trunk to a router with a subinterface per VLAN), or a Layer 3 switch with switched virtual interfaces (SVIs).")],
 [SUB('Basic configuration (Cisco IOS)', 'Typical commands.', S(None, code="vlan 10\n name SALES\ninterface Gi0/1\n switchport mode access\n switchport access vlan 10\ninterface Gi0/24\n switchport mode trunk\n switchport trunk allowed vlan 10,20\n switchport trunk native vlan 99")),
  SUB('VLAN hopping', 'Attacks and prevention.', S(None, bullets=["Switch spoofing: an attacker negotiates a trunk via DTP. Disable with `switchport nonegotiate` and set ports to access.", "Double tagging: an outer native-VLAN tag is stripped by the first switch, exposing the inner tag. Use an unused native VLAN and tag it, and never put users on it."])),
  SUB('Q-in-Q (802.1ad)', 'Provider bridging.', S(None, "Service providers stack an outer S-tag (TPID 0x88a8) on a customer's C-tag so customer VLANs stay private across the provider network.")),
  SUB('Voice VLANs and QoS', 'Priority.', S(None, "IP phones are often placed in a separate voice VLAN, and PCP bits mark voice for priority queuing.")),
  SUB('Troubleshooting', 'Typical faults.', S(None, bullets=["No connectivity across a trunk: VLAN not allowed or not created on the far switch.", "Native VLAN mismatch warnings (CDP).", "Host in the wrong VLAN or wrong subnet/gateway.", "Commands: show vlan brief, show interfaces trunk."]))],
 ["802.1Q adds a 4-byte tag with a 12-bit VLAN ID (1-4094).", "Access ports are untagged for one VLAN; trunks carry many VLANs tagged.", "Different VLANs need a router or Layer 3 switch to talk.", "Harden against switch spoofing and double tagging."],
 [IEEE8021, REF('Reference: IEEE 802.1Q (Wikipedia)', 'https://en.wikipedia.org/wiki/IEEE_802.1Q')])

write('stp',
 "Spanning Tree Protocol lets a switched network have redundant links without forwarding loops. Switches elect a root, compute loop-free paths toward it, and block the redundant ports.",
 [S('The problem: Layer 2 loops', "Ethernet frames have no TTL. With redundant links, a broadcast can circulate forever and multiply (a broadcast storm), while MAC tables flap as the same source appears on multiple ports. STP prevents this by blocking some ports."),
  S('Root bridge election', "Every switch has a Bridge ID: a 16-bit priority (default 32768, in steps of 4096) followed by its MAC address. The switch with the lowest Bridge ID becomes the root. Switches exchange BPDUs (every 2 seconds) announcing the root they believe in."),
  S('Port roles', None, bullets=["Root port: each non-root switch's single best path toward the root (lowest cumulative cost, then lowest sender ID).", "Designated port: on each segment, the port that offers the best path to the root; it forwards.", "Blocked/alternate port: everything else; receives BPDUs but forwards no data."]),
  S('Path cost', "Costs are summed along the path to the root. Typical IEEE short-method values: 10 Mb/s = 100, 100 Mb/s = 19, 1 Gb/s = 4, 10 Gb/s = 2. Lower total cost wins; ties are broken by sender bridge ID and port ID."),
  S('Port states in classic STP', None, bullets=["Blocking: discards data, listens to BPDUs.", "Listening: transitions, no learning yet (forward delay 15 s).", "Learning: builds the MAC table, still no forwarding (15 s).", "Forwarding: normal operation.", "Disabled: administratively down.", "Default timers: hello 2 s, forward delay 15 s, max age 20 s, so convergence takes 30-50 seconds."])],
 [SUB('Rapid STP (802.1w)', 'Faster convergence.', S(None, "RSTP collapses states into discarding, learning, and forwarding and adds a proposal/agreement handshake so point-to-point links can move to forwarding in a second or less. It adds alternate and backup port roles that are ready to take over immediately.")),
  SUB('PortFast and BPDU guard', 'Edge ports.', S(None, "Ports to end hosts should skip the delay (PortFast / edge port). BPDU Guard shuts such a port down if it ever receives a BPDU, preventing someone from attaching a switch and changing the topology.")),
  SUB('Per-VLAN and multiple spanning trees', 'PVST+, MSTP.', S(None, "PVST+ (Cisco) runs one tree per VLAN, enabling load balancing by choosing a different root per VLAN. MSTP (802.1s) maps groups of VLANs to a few instances, scaling better.")),
  SUB('Protecting the root', 'Guard features.', S(None, "Root Guard stops a port from accepting a superior BPDU that would move the root. Loop Guard prevents a port from becoming designated if BPDUs stop arriving. Set priorities deliberately so the root is a core switch, not an arbitrary old one.")),
  SUB('Diagnosing', 'Commands.', S(None, "`show spanning-tree` lists the root, port roles, and states per VLAN; unexpected root bridges and flapping topology-change counters point to problems.", code="Switch# show spanning-tree vlan 10\n  Root ID  Priority 24586  Address 0011.2233.4455\n  Gi0/1  Root FWD 4  128.1  P2p"))],
 ["STP elects the lowest Bridge ID as root, then keeps only the best loop-free paths.", "Roles: root, designated, blocked; costs sum toward the root.", "Classic STP converges in 30-50 s; RSTP in about a second.", "Use PortFast + BPDU Guard on edge ports and set the root deliberately."],
 [IEEE8021, REF('Reference: Spanning Tree Protocol (Wikipedia)', 'https://en.wikipedia.org/wiki/Spanning_Tree_Protocol')])

write('lacp',
 "Link aggregation bundles several physical links between two devices into one logical link for more bandwidth and redundancy. LACP, defined in IEEE 802.1AX (formerly 802.3ad), negotiates the bundle automatically.",
 [S('Why aggregate', None, bullets=["More total bandwidth than a single link.", "Redundancy: the bundle keeps working if a member fails.", "STP sees one logical link, so no member links are blocked."]),
  S('How LACP works', "Each side sends LACPDUs (EtherType 0x8809, slow-protocols multicast 01:80:C2:00:00:02) on every member link. They carry the system priority and MAC, a port key, and port state. Links whose partner information matches are bundled and activated; mismatches stay out. This detects misconfiguration and cabling mistakes that static bundles cannot."),
  S('Modes', None, bullets=["Active: sends LACPDUs and initiates negotiation.", "Passive: replies only if it receives LACPDUs; two passive ends never form a bundle.", "Static ('on'): no protocol, forced bundle; risky if the peer is misconfigured.", "LACPDU timing: fast (every 1 s) or slow (every 30 s)."]),
  S('Load balancing', "Frames are assigned to member links by hashing header fields so a single flow always uses the same link and stays in order. A single TCP connection therefore never exceeds one member's speed.", bullets=["L2 hash: source/destination MAC.", "L2+L3: plus IP addresses.", "L3+L4: plus TCP/UDP ports (best spread)."]),
  S('Requirements', "Members must have the same speed and duplex, belong to the same VLAN settings, and typically terminate on the same device (up to 8 active links is common).")],
 [SUB('Cisco configuration', 'EtherChannel.', S(None, code="interface range Gi0/1-2\n channel-group 1 mode active\ninterface Port-channel1\n switchport mode trunk\n! verify\nshow etherchannel summary")),
  SUB('Linux bonding', 'Modes.', S(None, "`mode=802.3ad` uses LACP; `active-backup` needs no switch support; `balance-xor` hashes statically; `balance-tlb/alb` adapt without switch cooperation.", code="ip link add bond0 type bond mode 802.3ad xmit_hash_policy layer3+4")),
  SUB('MLAG', 'Across two switches.', S(None, "Multi-chassis LAG presents two switches as one logical partner, so a server can aggregate links to both for switch-level redundancy. Implementations are vendor-specific (vPC, MC-LAG).")),
  SUB('Why a single flow does not speed up', 'Common misunderstanding.', S(None, "Four 1 Gb/s links give 4 Gb/s only across many flows. One file copy still caps at 1 Gb/s. Use multipath at higher layers (multipath TCP, application parallelism) to use more.")),
  SUB('Troubleshooting', 'Typical faults.', S(None, bullets=["Bundle not forming: both ends passive, mismatched modes or speeds, wrong VLAN config.", "Port shown as suspended or individual in the summary.", "Uneven traffic: poor hash for the traffic mix; change the hash policy."]))],
 ["LACP (IEEE 802.1AX) negotiates bundles with LACPDUs; at least one side must be active.", "Hashing keeps each flow on one link, so a single flow is limited to one member's speed.", "Members need matching speed and duplex.", "MLAG extends aggregation across two switches."],
 [IEEE8021, REF('Reference: Link aggregation (Wikipedia)', 'https://en.wikipedia.org/wiki/Link_aggregation')])

write('switch-diag',
 "Switch diagnostics means using show commands and counters to locate problems quickly: link state, MAC learning, VLANs, trunks, spanning tree, and bundles. Work from the physical layer upward.",
 [S('A systematic approach', None, bullets=["Layer 1: is the link up, at the right speed and duplex, with clean counters?", "Layer 2: are MACs learned, is the port in the right VLAN, is the trunk allowing it, is spanning tree forwarding?", "Layer 3: do the host and gateway share the subnet, and is the ARP entry present?", "Change one thing at a time and re-test."]),
  S('Core show commands (Cisco IOS style)', None, bullets=["show interfaces status: port up/down, VLAN, duplex, speed at a glance.", "show interfaces GigabitEthernet0/1: detailed counters.", "show mac address-table [address|interface|vlan]: where a device was learned.", "show vlan brief: VLANs and their access ports.", "show interfaces trunk: trunk ports, allowed and active VLANs, native VLAN.", "show spanning-tree [vlan N]: root bridge, port roles and states.", "show etherchannel summary: bundle membership and flags.", "show cdp neighbors / show lldp neighbors: what is attached to each port.", "show logging: link flaps, MAC flapping, err-disable events."]),
  S('Reading interface counters', None, bullets=["CRC / input errors: bad cable, interference, duplex mismatch.", "Runts and giants: collisions or MTU mismatch.", "Output drops: congestion.", "Late collisions: duplex mismatch or too-long cabling.", "Resets/flaps: unstable link or failing optic."]),
  S('Common symptoms and checks', None, bullets=["Port down/down: cable, remote end, or err-disabled (check `show interfaces status err-disabled`).", "Link up, no traffic: wrong VLAN, trunk not allowing the VLAN, or port security violation.", "Slow link: speed/duplex mismatch or errors.", "Intermittent: loops (STP), MAC flapping, or a failing cable.", "Host cannot reach gateway: ARP, VLAN, or default gateway misconfiguration."])],
 [SUB('Linux equivalents', 'Same questions on a host or bridge.', S(None, "`ip -s link` shows counters and errors; `ethtool eth0` shows speed and duplex; `bridge fdb show` is the MAC table; `bridge vlan show` lists VLANs; `ip neigh` is ARP.", code="$ ethtool eth0 | grep -E 'Speed|Duplex|Link'\n$ ip -s link show eth0")),
  SUB('Packet captures', 'See what is on the wire.', S(None, "SPAN/port mirroring copies traffic to an analyzer port; Wireshark or tcpdump then shows ARP, STP BPDUs, and LACPDUs directly. Filter on `arp`, `stp`, or `ether proto 0x8809`.")),
  SUB('Spotting a loop', 'Symptoms and fix.', S(None, "Symptoms: very high CPU, utilization near 100%, rapidly increasing broadcast counters, MAC flapping logs. Find the looping ports from the interface with the fastest-growing counters, shut one, and fix the topology or enable BPDU guard.")),
  SUB('Err-disable', 'Automatic protection.', S(None, "Ports shut themselves down on BPDU guard, port security, or link flap events. `show interfaces status err-disabled` names the cause; fix it, then `shutdown` / `no shutdown` (or configure auto-recovery).")),
  SUB('Baselines and documentation', 'Make future faults easy.', S(None, "Keep configuration backups, a port map, and baseline counters so deviations are obvious. Use SNMP or streaming telemetry to alert on error and utilization trends."))],
 ["Troubleshoot bottom-up: link, MAC/VLAN/trunk, STP, then IP.", "Know the key commands: interfaces status, mac address-table, vlan brief, trunk, spanning-tree, etherchannel.", "Counters tell the story: CRC means cabling, runts/giants mean MTU or collisions, drops mean congestion.", "Loops show as broadcast storms and MAC flapping."],
 [IEEE8021, REF('Reference: Cisco IOS switching command references', 'https://www.cisco.com/c/en/us/support/switches/index.html'), REF('Linux man-pages: bridge(8)', 'https://man7.org/linux/man-pages/man8/bridge.8.html')])
